#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Shape { Circle(u64), Rect(u64, u64), Dot }

fn area(s: &Shape) -> u64 {
    match s {
        Shape::Circle(r) => 3 * *r * *r,
        Shape::Rect(w, _) => *w * 2,
        Shape::Dot => 0,
    }
}

fn main() { println!("{}", area(&Shape::Rect(2, 3))); }

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Object { Default, Delete(u64), Constructor(Box<Object>) }

fn total(o: &Object) -> u64 {
    match o {
        Object::Default => 0,
        Object::Delete(n) => *n,
        Object::Constructor(inner) => total(inner) + 1,
    }
}

fn main() { println!("{}", total(&Object::Constructor(Box::new(Object::Delete(2))))); }

