fn classify(n: i64) -> String {
    if n < 0 {
        String::from("negative")
    } else if n == 0 {
        String::from("zero")
    } else {
        String::from("positive")
    }
}

fn describe(n: u32) -> String {
    let doubled = n + n;
    let label = classify(i64::from(doubled) - 10);
    format!("{n} doubled is {doubled} ({label})")
}

fn main() {
    println!("{}", describe(3));
    println!("{}", classify(-4));
