#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Tree { Leaf, Node(Box<Tree>, u64, Box<Tree>) }

mod tree {
    use super::Tree;

    pub fn size(t: &Tree) -> u64 {
        match t {
            Tree::Leaf => 0,
            Tree::Node(l, _, r) => size(l) + 1 + size(r),
        }
    }

    pub fn mirror(t: &Tree) -> Tree {
        match t {
            Tree::Leaf => Tree::Leaf,
            Tree::Node(l, v, r) => Tree::Node(Box::new(mirror(r)), *v, Box::new(mirror(l))),
        }
    }
}

fn main() {
    let t = Tree::Node(Box::new(Tree::Leaf), 3, Box::new(Tree::Leaf));
    assert_eq!(tree::mirror(&tree::mirror(&t)), t);
    assert_ne!(t, Tree::Leaf);
    println!("{}", tree::size(&t));
}

