#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Pair { Both(Box<List>, Box<List>), One(bool) }

fn sum(l: &List) -> i64 {
    match l {
        List::Nil => 0,
        List::Cons(h, t) => *h + sum(t),
    }
}

fn pick(p: &Pair) -> i64 {
    match p {
        Pair::Both(a, _) => sum(a),
        Pair::One(_) => 0,
    }
}

